package dev.savar.regista

import android.content.ComponentName
import android.content.Context
import android.content.pm.PackageManager
import androidx.annotation.DrawableRes

/**
 * Switchable launcher icons. Each is an `<activity-alias>` of MainActivity in the manifest (`.Icon<Name>`), and
 * exactly one is enabled. The drawables are generated by docs/icon/make.py: keep both lists in the same order.
 */
enum class AppIcon(val label: String, val alias: String, @DrawableRes val foreground: Int, @DrawableRes val status: Int) {
    WHISTLE("Whistle", ".IconWhistle", R.drawable.ic_fg_whistle, R.drawable.ic_stat_whistle),
    HOOKED("Hooked seams", ".IconHooked", R.drawable.ic_fg_hooked, R.drawable.ic_stat_hooked),
    SEAMS_DOT("Seams + dot", ".IconSeamsDot", R.drawable.ic_fg_seams_dot, R.drawable.ic_stat_seams_dot),
    SEAMS("Seams", ".IconSeams", R.drawable.ic_fg_seams, R.drawable.ic_stat_seams),
    PINWHEEL("Pinwheel", ".IconPinwheel", R.drawable.ic_fg_pinwheel, R.drawable.ic_stat_pinwheel),
    FLAG("Corner flag", ".IconFlag", R.drawable.ic_fg_flag, R.drawable.ic_stat_flag);

    fun component(ctx: Context) = ComponentName(ctx.packageName, "dev.savar.regista${alias}")

    companion object {
        val DEFAULT = WHISTLE

        /** The icon whose alias is enabled (the manifest default if none has been changed). */
        fun current(ctx: Context): AppIcon {
            val pm = ctx.packageManager
            return entries.firstOrNull { icon ->
                when (pm.getComponentEnabledSetting(icon.component(ctx))) {
                    PackageManager.COMPONENT_ENABLED_STATE_ENABLED -> true
                    PackageManager.COMPONENT_ENABLED_STATE_DEFAULT -> icon == DEFAULT
                    else -> false
                }
            } ?: DEFAULT
        }

        /**
         * Enables [icon]'s alias, then disables the others. DONT_KILL_APP keeps Regista open; the launcher picks up
         * the change within a few seconds. Some launchers (OxygenOS included) drop the old home-screen shortcut.
         */
        fun set(ctx: Context, icon: AppIcon) {
            val pm = ctx.packageManager
            pm.setComponentEnabledSetting(icon.component(ctx), PackageManager.COMPONENT_ENABLED_STATE_ENABLED, PackageManager.DONT_KILL_APP)
            entries.filter { it != icon }.forEach {
                pm.setComponentEnabledSetting(it.component(ctx), PackageManager.COMPONENT_ENABLED_STATE_DISABLED, PackageManager.DONT_KILL_APP)
            }
        }
    }
}
